<?php use App\Core\CSRF;$week=[1=>'Seg',2=>'Ter',3=>'Qua',4=>'Qui',5=>'Sex',6=>'Sáb',7=>'Dom']; ?>
<div class="sports-head"><div><span class="sports-kicker">TREINAR</span><h1>Aulas e Escolinha</h1><p>Submódulo opcional para turmas, professores, alunos e frequência.</p></div></div><div class="row g-4"><div class="col-xl-4"><form class="card border-0 shadow-sm" method="post" action="/sports/classes"><div class="card-body"><?=CSRF::field()?><h2 class="h5">Nova turma</h2><input class="form-control mb-2" name="name" placeholder="Beach Tennis Iniciante" required><input class="form-control mb-2" name="teacher_name" placeholder="Professor" required><input class="form-control mb-2" name="level" placeholder="Nível"><select class="form-select mb-2" name="court_id" required><?php foreach($courts as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><select class="form-select mb-2" name="modality_id"><option value="">Modalidade</option><?php foreach($modalities as $m):?><option value="<?=(int)$m['id']?>"><?=htmlspecialchars($m['name'])?></option><?php endforeach;?></select><div class="row g-2"><div class="col-6"><select class="form-select" name="weekday"><?php foreach($week as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select></div><div class="col-6"><input class="form-control" type="time" name="start_time" required></div><div class="col-6"><input class="form-control" type="number" name="duration_minutes" value="60" placeholder="Minutos"></div><div class="col-6"><input class="form-control" type="number" name="capacity" value="12" placeholder="Vagas"></div></div><input class="form-control my-2" name="monthly_amount" value="0,00" placeholder="Mensalidade"><button class="btn btn-primary w-100">Criar turma</button></div></form></div><div class="col-xl-8"><div class="sports-grid"><?php foreach($classes as $c):?><article class="sports-court-card"><div class="p-3"><span class="sports-status status-confirmed"><?=htmlspecialchars($c['status'])?></span><h2 class="h5 mt-2"><?=htmlspecialchars($c['name'])?></h2><p><?=htmlspecialchars($c['teacher_name'])?> · <?=htmlspecialchars($c['court_name'])?></p><small><?=$week[(int)$c['weekday']]??''?> <?=substr($c['start_time'],0,5)?> · <?=(int)$c['students']?>/<?=(int)$c['capacity']?> alunos · R$ <?=number_format((float)$c['monthly_amount'],2,',','.')?>/mês</small></div></article><?php endforeach;?></div></div></div>
